package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.*;import in.kabadiwala.connect.dto.LotDtos.*;import in.kabadiwala.connect.service.LotService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map; @RestController @RequestMapping("/api/v1") public class LotController {private final LotService s;public LotController(LotService s){this.s=s;}private String id(Authentication a){return a.getName();}private String role(Authentication a){return a.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");}@PostMapping("/collector/lots")@PreAuthorize("hasRole('COLLECTOR')")ApiResponse<?> create(Authentication a,@Valid @RequestBody Create r){return ApiResponse.ok("Lot created",s.create(id(a),r));}@PostMapping("/collector/lots/{lotId}/publish")@PreAuthorize("hasRole('COLLECTOR')")ApiResponse<?> publish(Authentication a,@PathVariable String lotId){return ApiResponse.ok("Lot published",s.publish(id(a),lotId));}@GetMapping("/collector/lots")@PreAuthorize("hasRole('COLLECTOR')")ApiResponse<?> mine(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){return ApiResponse.ok("Lots",s.mine(id(a),page,size));}@GetMapping("/lots/{lotId}")ApiResponse<?> detail(Authentication a,@PathVariable String lotId){return ApiResponse.ok("Lot",s.detail(id(a),role(a),lotId));}@GetMapping("/recycler/marketplace")@PreAuthorize("hasRole('RECYCLER')")ApiResponse<?> market(Authentication a,@RequestParam(required=false)String category,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){return ApiResponse.ok("Marketplace",s.marketplace(id(a),category,page,size));}@PostMapping("/recycler/lots/{lotId}/quotations")@PreAuthorize("hasRole('RECYCLER')")ApiResponse<?> quote(Authentication a,@PathVariable String lotId,@Valid @RequestBody Quote r){return ApiResponse.ok("Quotation submitted",s.quote(id(a),lotId,r));}@GetMapping("/lots/{lotId}/quotations")ApiResponse<?> quotes(Authentication a,@PathVariable String lotId){return ApiResponse.ok("Quotations",s.quotations(id(a),role(a),lotId));}@PostMapping("/collector/lots/{lotId}/quotations/{qid}/accept")@PreAuthorize("hasRole('COLLECTOR')")ApiResponse<?> accept(Authentication a,@PathVariable String lotId,@PathVariable String qid){return ApiResponse.ok("Quotation accepted",s.accept(id(a),lotId,qid));}@PostMapping("/recycler/lots/{lotId}/pickup")@PreAuthorize("hasRole('RECYCLER')")ApiResponse<?> pickup(Authentication a,@PathVariable String lotId,@RequestBody Schedule r){return ApiResponse.ok("Pickup scheduled",s.schedule(id(a),lotId,r));}@PatchMapping("/recycler/lots/{lotId}/pickup")@PreAuthorize("hasRole('RECYCLER')")ApiResponse<?> update(Authentication a,@PathVariable String lotId,@RequestBody Map<String,String>b){return ApiResponse.ok("Pickup updated",s.updatePickup(id(a),lotId,b.get("status")));}@GetMapping("/lots/{lotId}/pickup")ApiResponse<?> getPickup(Authentication a,@PathVariable String lotId){return ApiResponse.ok("Pickup",s.pickup(id(a),lotId));}@PostMapping("/recycler/lots/{lotId}/handover")@PreAuthorize("hasRole('RECYCLER')")ApiResponse<?> handover(Authentication a,@PathVariable String lotId,@Valid @RequestBody Handover r){return ApiResponse.ok("Handover verified",s.handover(id(a),lotId,r));}}
